-- Corrige somente a identificação das redes sociais informada pelo owner em 20/10/2026.
-- Catálogo 2026-10-20.7; 46 regras. Textos, estados, permissões e aprovações preservados.
-- Compara os registros anteriores completos para não sobrescrever alterações concorrentes.
-- Reversão: nova migração compensatória de títulos; não editar este arquivo após aplicado.
do $$
declare change jsonb; current_rule jsonb; changes jsonb := '[{"before":{"codigo":"instagram","categoria":"Instagram","titulo":"Instagram da Worki","texto":"Use instagram_desempenho para consultar métricas. Para publicar ou agendar foto, carrossel, Reels ou Story, confirme o tipo, a conta, o conteúdo final e os arquivos de data/arte escolhidos com artes_recentes. Use instagram_publicar; a publicação depende de aprovação e conferência do status na Zernio. Use instagram_post_editar e instagram_post_cancelar somente para posts ainda não publicados; ambas as ações exigem aprovação e a Zernio recusa alterações que não suporta. Consultas, Direct e automações seguem as regras específicas abaixo, somente quando as ferramentas estiverem disponíveis no executor. Não siga pessoas, faça prospecção autônoma ou envie mensagens frias. Curtida ou seguida não autoriza iniciar uma conversa.","ordem":25,"ativa":true},"after":{"codigo":"instagram","categoria":"Instagram","titulo":"Instagram de Herickson Maia","texto":"Use instagram_desempenho para consultar métricas. Para publicar ou agendar foto, carrossel, Reels ou Story, confirme o tipo, a conta, o conteúdo final e os arquivos de data/arte escolhidos com artes_recentes. Use instagram_publicar; a publicação depende de aprovação e conferência do status na Zernio. Use instagram_post_editar e instagram_post_cancelar somente para posts ainda não publicados; ambas as ações exigem aprovação e a Zernio recusa alterações que não suporta. Consultas, Direct e automações seguem as regras específicas abaixo, somente quando as ferramentas estiverem disponíveis no executor. Não siga pessoas, faça prospecção autônoma ou envie mensagens frias. Curtida ou seguida não autoriza iniciar uma conversa.","ordem":25,"ativa":true}},{"before":{"codigo":"linkedin","categoria":"LinkedIn","titulo":"LinkedIn pela Zernio","texto":"Use linkedin_contas para contas conectadas, linkedin_organizacoes para páginas administradas e linkedin_desempenho para métricas. Use linkedin_publicar para texto ou imagem e para agendamento nas modalidades efetivamente expostas pela ferramenta. Confirme conta, organização quando aplicável, texto final, mídia e horário antes de solicitar a aprovação numerada. Publicação pública exige aprovação e leitura do status na Zernio. Não ofereça DMs/InMail, comentários, PDF, vídeo, enquete, eventos ou newsletters se essas operações não estiverem implementadas nas ferramentas disponíveis.","ordem":32,"ativa":true},"after":{"codigo":"linkedin","categoria":"LinkedIn","titulo":"LinkedIn de Herickson Maia","texto":"Use linkedin_contas para contas conectadas, linkedin_organizacoes para páginas administradas e linkedin_desempenho para métricas. Use linkedin_publicar para texto ou imagem e para agendamento nas modalidades efetivamente expostas pela ferramenta. Confirme conta, organização quando aplicável, texto final, mídia e horário antes de solicitar a aprovação numerada. Publicação pública exige aprovação e leitura do status na Zernio. Não ofereça DMs/InMail, comentários, PDF, vídeo, enquete, eventos ou newsletters se essas operações não estiverem implementadas nas ferramentas disponíveis.","ordem":32,"ativa":true}}]'::jsonb;
begin
 for change in select value from jsonb_array_elements(changes) loop
  select jsonb_build_object('codigo',codigo,'categoria',categoria,'titulo',titulo,'texto',texto,'ordem',ordem,'ativa',ativa) into current_rule from public.maia_rules where codigo=change->'before'->>'codigo' for update;
  if current_rule is distinct from change->'before' and current_rule is distinct from change->'after' then
   raise exception 'Regra % divergente; correção de identidade interrompida', change->'before'->>'codigo';
  end if;
 end loop;
 update public.maia_rules r set titulo=c.value->'after'->>'titulo' from jsonb_array_elements(changes) c(value) where r.codigo=c.value->'after'->>'codigo';
end $$;
